const systemHistory = `-- name: SystemHistory :many
SELECT CAST(MAX(ts) AS INTEGER) AS ts, AVG(cpu_pct) AS cpu_pct, CAST(AVG(mem_used) AS INTEGER) AS mem_used,
       CAST(MAX(mem_total) AS INTEGER) AS mem_total, AVG(load1) AS load1
FROM system_stats WHERE ts >= ?1 AND ?2 > 0
GROUP BY ts / ?2 ORDER BY ts ASC
`

type SystemHistoryParams struct {
	Cutoff int64       `json:"cutoff"`
	Bucket interface{} `json:"bucket"`
}

type SystemHistoryRow struct {
	Ts       int64    `json:"ts"`
	CpuPct   *float64 `json:"cpu_pct"`
	MemUsed  int64    `json:"mem_used"`
	MemTotal int64    `json:"mem_total"`
	Load1    *float64 `json:"load1"`
}

func (q *Queries) SystemHistory(ctx context.Context, arg SystemHistoryParams) ([]SystemHistoryRow, error) {
	rows, err := q.db.QueryContext(ctx, systemHistory, arg.Cutoff, arg.Bucket)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SystemHistoryRow{}
	for rows.Next() {
		var i SystemHistoryRow
		if err := rows.Scan(
			&i.Ts,
			&i.CpuPct,
			&i.MemUsed,
			&i.MemTotal,
			&i.Load1,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
